-- =====================================================================
-- 50-day demo dataset for client "Sharafath"  (deterministic, re-runnable)
-- Resolves clientId + coachId from the existing client row — no ids to edit.
-- Shape: build → overreach spike → deload → build → rough patch → recovery.
-- =====================================================================
delete from wellness where id like 'sd50-%';
delete from wearable where id like 'sd50-%';
delete from srpe where id like 'sd50-%';
delete from resistance where id like 'sd50-%';
delete from cardio where id like 'sd50-%';
delete from maxes where id like 'sd50-%';
delete from sessions where id like 'sd50-%';
delete from workouts where id like 'sd50-%';
delete from prescriptions where id like 'sd50-%';

with c as (select id, "coachId" from clients where name ilike '%sharafath%' limit 1)
) as v;

with c as (select id, "coachId" from clients where name ilike '%sharafath%' limit 1)
) as v;

