) as v;

with c as (select id, "coachId" from clients where name ilike '%sharafath%' limit 1)
) as v;

with c as (select id, "coachId" from clients where name ilike '%sharafath%' limit 1)
) as v;

-- Track the three main lifts so Current Lifts Performance is populated.
with c as (select id, "coachId" from clients where name ilike '%sharafath%' limit 1)
update clients set "trackedLifts" = '["Back Squat","Bench Press","Deadlift"]'::jsonb
where id = (select id from c);
